def alphabeta(node, depth, alpha, beta, maximizing, eval_fn):
    if depth == 0 or node.is_terminal():
        return eval_fn(node)

    if maximizing:
        value = float('-inf')
        for child in node.generate_moves():
            value = max(value, alphabeta(child, depth - 1, alpha, beta, ______, eval_fn))
            alpha = max(alpha, value)
            if alpha ______ beta:
                break                # prune branch
        return value
    else:
        value = float('inf')
        for child in node.generate_moves():
            value = min(value, alphabeta(child, depth - 1, alpha, beta, ______, eval_fn))
            beta = min(beta, value)
            if beta ______ alpha:
                break                # prune branch
        return value
